#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""
模擬會議逐字稿測試資料

提供多種模擬會議逐字稿，用於測試 System Prompt 在不同情境下的表現。
涵蓋情境：
1. 標準政府機關會議情境
2. 含技術討論的專案會議
3. 有多個待辦事項和決議的複雜會議
4. 含模糊資訊需標註「(待確認)」的情境
5. 邊界情況：極短逐字稿、極長逐字稿
"""
from dataclasses import dataclass
from typing import List, Optional


@dataclass
class MockTranscript:
    """模擬逐字稿測試資料結構"""
    name: str  # 測試案例名稱
    description: str  # 情境描述
    transcript: str  # 逐字稿內容
    expected_sections: List[str]  # 預期應包含的區塊
    expected_keywords: List[str]  # 預期應出現的關鍵字
    has_ambiguous_info: bool = False  # 是否包含模糊資訊
    expected_action_items: int = 0  # 預期待辦事項數量


